entries[301411] = { ["name"] = "Comfortable Rider's Barding", ["text"] = "3.5 sec cast\nReagents:\nCoarse Leather Barding (2), Seabreeze Saddle Blanket (2)\nCraft a Comfortable Rider's Barding.\nProfession:\nBattle for Azeroth Leatherworking (150)\nTrainer:\nJada\nZone:\nNazjatar\nCost:\n65\n\nComfortable Rider's Barding\nUse: Equip in your mount equipment slot to prevent you from being dazed while mounted. Does not work in Battlegrounds or Arenas.\n10" }
entries[301412] = { ["name"] = "Light-Step Hoofplates", ["text"] = "3.5 sec cast\nTools: Runed Enchanting Rod\nReagents:\nUmbra Shard (2), Gloom Dust (30), Monel-Hardened Hoofplates\nCreate an enchanted set of Light-Step Hoofplates.\nProfession Trainer:\nBattle for Azeroth Enchanting (155)\nCost:\n92\n50\n\nLight-Step Hoofplates\n(0)\nUse: Equip in your Mount Equipment slot to increase your mount's ground speed by 20%. Does not work in Battlegrounds or Arenas and does not stack with other mount speed effects.\n10" }
entries[301413] = { ["name"] = "Inflatable Mount Shoes", ["text"] = "3.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nMonel-Hardened Hoofplates , Dredged Leather Bladder (8)\nCraft a set of Inflatable Mount Shoes.\nProfession:\nBattle for Azeroth Blacksmithing (150)\nTrainer:\nJada\nZone:\nNazjatar\nCost:\n65\n\nInflatable Mount Shoes\nUse: Equip in your mount equipment slot to allow you to walk across water while mounted. Any damage will cancel the effect. Does not work in Battlegrounds or Arenas.\n10" }
